$zip = [System.IO.Compression.ZipFile]::Open($ZipPath, 'Update')
try {
    $patched = 0
    foreach ($entry in @($zip.Entries)) {
        if ($entry.FullName -notmatch '\.(js|html|json|css)$') { continue }
        $reader = New-Object System.IO.StreamReader($entry.Open(), [System.Text.Encoding]::UTF8)
        $content = $reader.ReadToEnd()
        $reader.Close()

        $original = $content
        foreach ($pair in $replacements) {
            $content = $content.Replace($pair[0], $pair[1])
        }
        if ($content -ne $original) {
            $fullName = $entry.FullName
            $entry.Delete()
            $newEntry = $zip.CreateEntry($fullName)
            $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
            $writer = New-Object System.IO.StreamWriter($newEntry.Open(), $utf8NoBom)
            $writer.Write($content)
            $writer.Close()
            $patched++
            Write-Host "patch_ui_bundle: rewrote $fullName"
        }
    }
    Write-Host "patch_ui_bundle: $patched file(s) patched in $ZipPath"
}
finally {
    $zip.Dispose()
}
